fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // Check that all vectors have the same length
    let n = s1.len();
    assert_eq!(n, s2.len(), "s1 and s2 must have the same length");
    assert_eq!(n, s3.len(), "s1 and s3 must have the same length");
    
    // Pre-allocate the result vector with exact capacity
    let mut result = Vec::with_capacity(3 * n);
    
    // Interleave elements from all three vectors
    for i in 0..n {
        result.push(s1[i]);
        result.push(s2[i]);
        result.push(s3[i]);
    }
    
    result
}